<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { NButton, NCheckbox, NDrawer, NDrawerContent, NInput, NSelect, NTabs, NTabPane } from 'naive-ui'
import { modelApi, memberError, type Model, type ModelInput, type Deployments, type Usage } from './api'
import ErrorBanner from '../../shared/ui/ErrorBanner.vue'
import EmptyState from '../../shared/ui/EmptyState.vue'
import { formatBytes, formatDate } from '../../shared/ui/resource'
import './models.css'
const route=useRoute(),router=useRouter()
const tab=ref('small'),items=ref<Model[]>([]),cursor=ref<string|null>(null),query=ref(''),validation=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const referenceCounts=ref<Record<string,number|null>>({})
const deployments=ref<Deployments|null>(null),selected=ref<Model|null>(null),refs=ref<Awaited<ReturnType<typeof modelApi.references>>>([]),refError=ref('')
const showForm=ref(false),base=ref<Model|null>(null),file=ref<File|null>(null),progress=ref(0),uploaded=ref(''),formError=ref(''),archiveAck=ref(false)
const form=reactive({name:'',version:'',runtime_type:'',template_name:'',template_version:'',targets:'',rules:'',regions:'',durations:'',limitations:'',defaults:'{}'})
const choices=reactive<Record<Usage,string|null>>({requirement_parse:null,multimodal_analysis:null})
const usages:{key:Usage;label:string}[]=[{key:'requirement_parse',label:'自然语言需求解析'},{key:'multimodal_analysis',label:'多模态能力与证据分析'}]
const stateLabel=(m:Model)=>m.status==='archived'?'已归档':({pending:'待算法校验',passed:'校验通过',failed:'校验失败'})[m.validation]
const split=(value:string)=>[...new Set(value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean))]
const selectionOptions=(usage:Usage)=>deployments.value?.items.filter(d=>d.usages.includes(usage)).map(d=>({label:`${d.name} · ${d.version} · ${d.health==='healthy'?'健康':'不可用'}`,value:d.id,disabled:d.health!=='healthy'}))??[]
const formTitle=computed(()=>base.value?'创建新版本（原版本保留）':'导入小模型与绑定模板')
let generation=0
async function load(more=false){if(loading.value)return;loading.value=true;error.value='';try{const page=await modelApi.list(query.value,validation.value,more?cursor.value??undefined:undefined);items.value=more?[...items.value,...page.items]:page.items;cursor.value=page.next_cursor??null;void Promise.all(page.items.map(async m=>{const key=m.id+':'+m.version;try{referenceCounts.value[key]=(await modelApi.references(m)).length}catch{referenceCounts.value[key]=null}}))}catch(e){error.value=memberError(e)}finally{loading.value=false}}
async function loadDeployments(){try{deployments.value=await modelApi.deployments();for(const s of deployments.value.selections)choices[s.usage]=s.deployment_id??null}catch(e){error.value=memberError(e)}}
async function inspect(m:Model){const g=++generation;selected.value=m;archiveAck.value=false;refs.value=[];refError.value='';try{const result=await modelApi.references(m);if(g===generation)refs.value=result}catch(e){if(g===generation)refError.value=memberError(e)}}
async function openForm(m?:Model){base.value=m??null;file.value=null;uploaded.value=m?.file_id??'';progress.value=0;formError.value='';Object.assign(form,{name:m?.name??'',version:'',runtime_type:m?.runtime_type??'',template_name:m?.template.name??'',template_version:'',targets:m?.template.targets.join(', ')??'',rules:m?.template.rules.join(', ')??'',regions:m?.template.requires_region?.join(', ')??'',durations:m?.template.requires_duration?.join(', ')??'',limitations:m?.template.limitations?.join('\n')??'',defaults:JSON.stringify(m?.template.defaults??{},null,2)});showForm.value=true}
function chooseFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;uploaded.value=file.value?'':base.value?.file_id??'';progress.value=0}
function closeForm(){if(busy.value)return;if(window.confirm('关闭导入表单？尚未提交的字段不会保存。'))showForm.value=false}
function operationKey(payload:unknown){const signature=JSON.stringify(payload),old=sessionStorage.getItem('vision.model.import');if(old){try{const saved=JSON.parse(old) as {signature:string;key:string};if(saved.signature===signature)return saved.key}catch{/* invalid storage */}}const key=crypto.randomUUID();sessionStorage.setItem('vision.model.import',JSON.stringify({signature,key}));return key}
async function submit(){
  if(busy.value)return;formError.value=''
  let defaults:ModelInput['template']['defaults']
  try{defaults=JSON.parse(form.defaults) as ModelInput['template']['defaults'];if(!defaults||Array.isArray(defaults)||typeof defaults!=='object')throw Error()}catch{formError.value='默认业务参数须为 JSON 对象。';return}
  if(!form.name.trim()||!form.version||!form.runtime_type.trim()||!form.template_name.trim()||!form.template_version||!split(form.targets).length||!split(form.rules).length){formError.value='请完整填写名称、版本、运行接口、目标和规则。';return}
  if(!file.value&&!uploaded.value){formError.value='请选择本地模型文件。';return}
  busy.value=true
  try{
    if(file.value&&!uploaded.value){const result=await modelApi.upload(file.value,n=>progress.value=n);uploaded.value=result.id}
    const body:ModelInput={name:form.name,version:form.version,runtime_type:form.runtime_type,file_id:uploaded.value,template:{name:form.template_name,version:form.template_version,targets:split(form.targets),rules:split(form.rules),requires_region:split(form.regions),requires_duration:split(form.durations),limitations:split(form.limitations),defaults}}
    let result=await modelApi.create(body,operationKey([base.value?.id,body]),base.value?.id)
    // Imports are durable even if the verifier is temporarily unavailable.
    let verifyNotice=''
    try{result=await modelApi.verify(result)}catch(e){verifyNotice=`管理项已保存，校验未完成：${memberError(e)}`}
    showForm.value=false;await load();await inspect(result);notice.value=verifyNotice||result.validation_message
  }catch(e){formError.value=memberError(e)}finally{busy.value=false}
}
async function verify(m:Model){busy.value=true;error.value='';try{const result=await modelApi.verify(m);notice.value=result.validation_message;await inspect(result);await load()}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function archive(){if(!selected.value||busy.value)return;if(!window.confirm('确认归档此模型版本？历史配置和文件保留，归档版本不再用于新任务。'))return;busy.value=true;error.value='';try{await inspect(await modelApi.archive(selected.value,archiveAck.value));await load();notice.value='模型版本已归档，历史配对保留。'}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function apply(usage:Usage){const current=deployments.value?.selections.find(s=>s.usage===usage),choice=choices[usage];if(!current||!choice)return;busy.value=true;error.value='';try{await modelApi.select(usage,choice,current.row_version);await loadDeployments();notice.value='用途绑定已更新，将用于后续新请求；已有运行快照保留。'}catch(e){error.value=memberError(e);await loadDeployments()}finally{busy.value=false}}
watch(()=>route.params.id,async id=>{if(id)try{await inspect(await modelApi.detail(String(id),typeof route.query.version==='string'?route.query.version:undefined))}catch(e){error.value=memberError(e)}})
onMounted(async()=>{await Promise.all([load(),loadDeployments()]);if(route.params.id)try{await inspect(await modelApi.detail(String(route.params.id),typeof route.query.version==='string'?route.query.version:undefined))}catch(e){error.value=memberError(e)}})
</script>
<template>
  <div class="page-heading"><div><h1>模型管理</h1><p>维护本地模型与模板版本，为监测任务提供经过校验的能力。</p></div><NButton type="primary" :disabled="busy" @click="openForm()">导入小模型</NButton></div>
  <ErrorBanner :error="error" @retry="load();loadDeployments()"/><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <NTabs v-model:value="tab" type="line" animated><NTabPane name="small" tab="小模型与对应模板">
    <div class="notice">模型与模板按版本一一绑定。文件上传与 SHA-256 检查不代表算法校验通过；修改管理项请创建新版本。</div>
    <div class="model-workspace"><section class="panel"><form class="toolbar" @submit.prevent="load()"><NInput v-model:value="query" aria-label="搜索模型" :input-props="{'aria-label':'搜索模型'}" placeholder="搜索模型或模板名称" clearable/><NSelect v-model:value="validation" aria-label="模型校验状态" :options="[{label:'全部校验状态',value:''},{label:'待校验',value:'pending'},{label:'通过',value:'passed'},{label:'失败',value:'failed'}]"/><NButton :loading="loading" attr-type="submit">查询</NButton></form>
      <div v-if="loading" class="loading-line"/><EmptyState v-if="!items.length&&!loading" title="没有模型管理项" description="导入本地文件并声明对应模板，实际可用性由算法适配器校验。"/>
      <div v-else class="table-wrap"><table><thead><tr><th>模型 / 模板</th><th>版本</th><th>校验与状态</th><th>配置引用</th><th>更新</th><th>操作</th></tr></thead><tbody><tr v-for="m in items" :key="m.id+':'+m.version" :class="{selected:selected?.id===m.id&&selected.version===m.version}"><td class="wrap"><strong>{{m.name}}</strong><small>{{m.template.name}} · {{m.runtime_type}}</small><span v-if="m.data_origin==='mock'" class="model-demo">模拟</span></td><td>{{m.version}}<small>模板 {{m.template.version}}</small></td><td><span class="model-state" :class="m.validation">{{stateLabel(m)}}</span></td><td>{{referenceCounts[m.id+':'+m.version]??'待确认'}}</td><td>{{formatDate(m.updated_at)}}</td><td><NButton size="small" @click="inspect(m)">详情</NButton></td></tr></tbody></table></div>
      <NButton v-if="cursor" :loading="loading" @click="load(true)">加载更多</NButton>
    </section>
    <aside v-if="selected" class="panel model-detail"><div class="panel-title"><h2>{{selected.name}} · {{selected.version}}</h2><NButton size="tiny" @click="selected=null;generation++">关闭</NButton></div><p class="model-state" :class="selected.validation">{{stateLabel(selected)}}</p><p>{{selected.validation_message}}</p><dl class="detail-meta"><div><dt>文件大小</dt><dd>{{formatBytes(selected.size_bytes)}}</dd></div><div><dt>运行接口</dt><dd>{{selected.runtime_type}}</dd></div><div class="wide"><dt>SHA-256</dt><dd class="model-hash">{{selected.checksum}}</dd></div><div class="wide"><dt>目标 / 规则</dt><dd>{{selected.template.targets.join('、')}} / {{selected.template.rules.join('、')}}</dd></div><div class="wide"><dt>能力限制</dt><dd>{{selected.template.limitations?.join('；')||'未提供；必须由算法适配器核验'}}</dd></div></dl>
      <h3>受影响配置（{{refs.length}}）</h3><ErrorBanner :error="refError" @retry="inspect(selected!)"/><p v-if="!refs.length&&!refError" class="muted">未查询到引用。</p><div v-for="r in refs" :key="r.revision_id" class="model-reference"><RouterLink :to="`/agents/${r.agent_id}/config`">{{r.agent_name}} · v{{r.revision_no}}</RouterLink><small>{{r.active_run_ids?.length?'存在活动运行':r.runtime_checked?'未运行':'运行状态未知'}}</small></div>
      <div class="model-actions"><NButton :disabled="busy||selected.status==='archived'" @click="verify(selected!)">重新校验</NButton><NButton :disabled="busy" @click="openForm(selected!)">创建新版本</NButton></div><NCheckbox v-if="refs.length" v-model:checked="archiveAck" :disabled="busy">我已核对历史配置引用，了解归档影响</NCheckbox><NButton type="error" secondary :disabled="busy||!!refError||selected.status==='archived'" @click="archive">归档此版本</NButton><p class="hint">活动运行引用会被后端拒绝。历史文件与事件不会被删除。</p>
    </aside></div>
  </NTabPane><NTabPane name="llm" tab="本地大模型">
    <div class="notice">此处只选择已部署在本机的模型。当前没有部署服务时显示空列表，不会下载或调用云端模型。</div>
    <div class="model-llm-grid"><section v-for="u in usages" :key="u.key" class="panel"><h2>{{u.label}}</h2><p>后续新请求使用这里选定的模型及版本。</p><NSelect v-model:value="choices[u.key]" :options="selectionOptions(u.key)" :disabled="busy" :aria-label="u.label" placeholder="暂无可用部署 / 请选择"/><NButton type="primary" :disabled="busy||!choices[u.key]||choices[u.key]===deployments?.selections.find(s=>s.usage===u.key)?.deployment_id" @click="apply(u.key)">应用用途选择</NButton></section></div>
    <section class="panel"><EmptyState v-if="!deployments?.items.length" title="尚未接入本地大模型部署" description="由算法同事部署模型并接入服务适配器后，健康状态与可用用途会显示在这里。"/><div v-else class="table-wrap"><table><thead><tr><th>名称 / 版本</th><th>输入</th><th>部署位置</th><th>健康状态</th><th>当前绑定</th></tr></thead><tbody><tr v-for="d in deployments.items" :key="d.id"><td>{{d.name}} · {{d.version}}</td><td>{{d.inputs.join('、')}}</td><td>{{d.location}}</td><td>{{d.health==='healthy'?'健康':d.health==='unknown'?'未知':'不可用'}}</td><td>{{d.selected_usages?.map(u=>usages.find(v=>v.key===u)?.label).join('、')||'未绑定'}}</td></tr></tbody></table></div></section>
  </NTabPane></NTabs>
  <NDrawer :show="showForm" :width="660" :mask-closable="!busy" :close-on-esc="!busy" @update:show="closeForm"><NDrawerContent :title="formTitle" closable><ErrorBanner :error="formError" :retryable="false"/><form id="model-form" @submit.prevent="submit"><fieldset :disabled="busy" class="model-fields"><div class="field-grid"><div class="field"><label>模型名称</label><NInput v-model:value="form.name" :disabled="busy" aria-label="模型名称" :input-props="{'aria-label':'模型名称'}" :maxlength="160"/></div><div class="field"><label>新模型版本</label><NInput v-model:value="form.version" :disabled="busy" aria-label="新模型版本" :input-props="{'aria-label':'新模型版本'}" placeholder="例如 1.0.0"/></div></div><div class="field"><label>本地模型文件（作为惰性文件保存，不加载执行）</label><input type="file" aria-label="本地模型文件" :disabled="busy" @change="chooseFile"/><p v-if="base&&!file" class="hint">沿用原文件；若替换，请选择新文件。</p><p v-if="progress">文件上传 {{progress}}%</p></div><div class="field"><label>兼容运行接口 / 执行器类型</label><NInput v-model:value="form.runtime_type" :disabled="busy" aria-label="运行接口" :input-props="{'aria-label':'运行接口'}" placeholder="由算法提供方声明，暂不限定文件格式"/></div><div class="field-grid"><div class="field"><label>绑定模板名称</label><NInput v-model:value="form.template_name" :disabled="busy" aria-label="模板名称" :input-props="{'aria-label':'模板名称'}"/></div><div class="field"><label>新模板版本</label><NInput v-model:value="form.template_version" :disabled="busy" aria-label="新模板版本" :input-props="{'aria-label':'新模板版本'}"/></div></div><div class="field"><label>支持目标（英文标识，以逗号分隔）</label><NInput v-model:value="form.targets" :disabled="busy" aria-label="支持目标" :input-props="{'aria-label':'支持目标'}" placeholder="例如 person；填写不代表已经具备该能力"/></div><div class="field"><label>支持规则（英文标识，以逗号分隔）</label><NInput v-model:value="form.rules" :disabled="busy" aria-label="支持规则" :input-props="{'aria-label':'支持规则'}" placeholder="由对应执行器声明"/></div><div class="field-grid"><div class="field"><label>需要区域的规则</label><NInput v-model:value="form.regions" :disabled="busy" aria-label="需要区域的规则" :input-props="{'aria-label':'需要区域的规则'}"/></div><div class="field"><label>需要时长的规则</label><NInput v-model:value="form.durations" :disabled="busy" aria-label="需要时长的规则" :input-props="{'aria-label':'需要时长的规则'}"/></div></div><div class="field"><label>默认业务参数（JSON，任务时长仍须用户确认）</label><NInput v-model:value="form.defaults" type="textarea" :disabled="busy" aria-label="默认业务参数" :input-props="{'aria-label':'默认业务参数'}"/></div><div class="field"><label>适用限制（每行一项）</label><NInput v-model:value="form.limitations" type="textarea" :disabled="busy" aria-label="适用限制" :input-props="{'aria-label':'适用限制'}"/></div></fieldset></form><template #footer><div class="model-actions"><NButton :disabled="busy" @click="closeForm">取消</NButton><NButton type="primary" :loading="busy" attr-type="submit" form="model-form">保存并请求校验</NButton></div></template></NDrawerContent></NDrawer>
</template>
